const o="/api";function c(e){return new Promise(t=>setTimeout(t,e))}async function r(e,t={},n=1e4){const a=new AbortController,i=setTimeout(()=>a.abort(),n);try{const s=await fetch(e,{...t,signal:a.signal});return clearTimeout(i),s}catch(s){throw clearTimeout(i),s.name==="AbortError"?new Error(`Request timeout after ${n}ms`):s}}async function l(){const e=await r(`${o}/model`);if(!e.ok)throw new Error("Failed to fetch decision model");return e.json()}async function d(e){const t=await r(`${o}/score`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({answers:e})});if(!t.ok)throw new Error("Failed to calculate score");return t.json()}async function u(){const e=await r(`${o}/release-planner/copilot-studio`,{},2e4);if(!e.ok)throw new Error(`Failed to fetch Copilot Studio release planner data (HTTP ${e.status})`);const t=e.headers.get("content-type")||"";if(!t.includes("application/json"))throw new Error(`Release planner endpoint returned non-JSON response (HTTP ${e.status}, content-type: ${t||"unknown"}). The backend deployment may be out of date; redeploy the API/server package.`);return e.json()}async function p(){const e=await r(`${o}/foundry/news`,{},2e4);if(!e.ok)throw new Error(`Failed to fetch Microsoft Foundry news (HTTP ${e.status})`);const t=e.headers.get("content-type")||"";if(!t.includes("application/json"))throw new Error(`Foundry news endpoint returned non-JSON response (HTTP ${e.status}, content-type: ${t||"unknown"})`);return e.json()}async function w(){let e=null;for(let t=1;t<=2;t++)try{const n=await r(`${o}/readiness/model`,{},15e3);if(!n.ok)throw new Error(`Failed to fetch readiness model (HTTP ${n.status})`);return n.json()}catch(n){e=n instanceof Error?n:new Error("Failed to fetch readiness model"),t<2&&await c(750)}throw e||new Error("Failed to fetch readiness model")}async function f(e){const t=await r(`${o}/readiness/assess`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({answers:e})},2e4);if(!t.ok){const n=await t.json().catch(()=>null);throw new Error((n==null?void 0:n.message)||"Failed to assess readiness")}return t.json()}export{u as a,p as b,d as c,w as d,f as e,l as g};
